func (s *PlaceOrderService) Place(ctx context.Context, cmd PlaceOrder) (OrderID, error) {
    tx, err := s.db.BeginTx(ctx, nil)
    if err != nil { return 0, err }
    defer tx.Rollback()                              // no-op after Commit
    customer, err := s.customers.Get(ctx, tx, cmd.CustomerID)
    if err != nil { return 0, err }
    order, err := customer.PlaceOrder(cmd.Items)     // the domain decides
    if err != nil { return 0, err }
    if err := s.orders.Add(ctx, tx, order); err != nil { return 0, err }
    if err := tx.Commit(); err != nil { return 0, err }
    return order.ID, nil
}

