func (s *PlaceOrderService) Place(ctx context.Context, cmd PlaceOrder) (OrderID, error) {
    var id OrderID
    err := s.uow.Execute(ctx, func(tx Store) error {   // commits on nil, rolls back on error
        customer, err := tx.Customers().Get(ctx, cmd.CustomerID)
        if err != nil { return err }
        order, err := customer.PlaceOrder(cmd.Items)   // the domain decides
        if err != nil { return err }
        if err := tx.Orders().Add(ctx, order); err != nil { return err }
        id = order.ID
        return nil
    })
    return id, err
}
